const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
