  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
    expect(screen.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
  });

  test('renders one radio swatch per populated colour', () => {
    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
  });

  test('marks exactly the swatch matching selectedValue as checked', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const checked = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('aria-checked') === 'true');
    expect(checked).toHaveLength(1);
    expect(checked[0]).toHaveAccessibleName('Ivory');
  });

  test('AC 5: filters out colours whose index image is not populated', () => {
    const { container } = renderGroup({ values: [BAY_BLUE, IVORY, BLACK, ROSE_UNPOPULATED, GOLD_UNPOPULATED] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
    expect(container.textContent).not.toContain('Rose Pink');
    expect(container.textContent).not.toContain('Gold');
  });

  test('AC 5 filters on image population only, never a stock/orderability-like field', () => {
    // This component's own prop type carries no stock field at all — the extra property below
    // proves the filter cannot be keying on one, since there is nowhere in the type for it to
    // come from other than this deliberately-bolted-on test fixture.
    const valueWithExtraField: ZimmColourSwatchValue & { orderable: boolean } = { ...BAY_BLUE, orderable: false };
    renderGroup({ values: [valueWithExtraField, IVORY] });
    expect(screen.getByRole('radio', { name: 'Bay Blue' })).toBeInTheDocument();
  });

  test('collapses to the label-only branch when only one of several colours is populated', () => {
    renderGroup({
      selectedName: 'Bay Blue',
      selectedValue: 'BAYBL',
      values: [BAY_BLUE, ROSE_UNPOPULATED, GOLD_UNPOPULATED],
    });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });

  test('keeps exactly one swatch in the roving tab order at a time', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const tabbable = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('tabindex') === '0');
    expect(tabbable).toHaveLength(1);
