    // literal var() declaration, not a resolved px value: jsdom's getComputedStyle does not
    // substitute a custom property (see zimmColourSwatch/index.test.tsx's own note on this).
    const styles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
    expect(styles.gap).toBe('var(--zimm-scale-xs)');
  });

  test('mounts directly on the page containing the actual selection, not always page 1 (pagination regression)', () => {
    // 6 populated colours, selection is the 6th (index 5) — beyond the first 4-wide page. Before
    // the fix, `pageStart` always started at 0 regardless of where the selection sat, so this
    // exact shape rendered page 1 (indices 0-3) with zero items aria-checked and zero items
    // tabbable, since the selected colour was never part of the rendered window.
    const SIXTH_COLOUR: ZimmColourSwatchValue = {
      value: 'NAVY',
      name: 'Navy',
      href: '/p.html?color=NAVY',
      imageUrl: IMAGE('navy'),
    };
    const sixColours: ZimmColourSwatchValue[] = [
      BAY_BLUE,
      IVORY,
      BLACK,
      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
      SIXTH_COLOUR,
    ];

    // No interaction of any kind above this line — this asserts the component's very first render.
    renderGroup({ selectedName: SIXTH_COLOUR.name, selectedValue: SIXTH_COLOUR.value, values: sixColours });

    const radios = screen.getAllByRole('radio');
    const checkedRadios = radios.filter((radio) => radio.getAttribute('aria-checked') === 'true');
    const tabbableRadios = radios.filter((radio) => radio.getAttribute('tabindex') === '0');

    expect(checkedRadios).toHaveLength(1);
    expect(checkedRadios[0]).toHaveAttribute('aria-checked', 'true');
    expect(checkedRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);

    expect(tabbableRadios).toHaveLength(1);
    expect(tabbableRadios[0]).toHaveAttribute('tabindex', '0');
    expect(tabbableRadios[0]).toHaveAccessibleName(SIXTH_COLOUR.name);
  });

  test('reserves a fixed page-width footprint once paginated, so the row does not resize on a shorter final page (layout regression)', async () => {
    // 6 populated colours -> paginated (> SWATCHES_PER_PAGE = 4): page 1 renders a full 4-swatch
    // window, the final page only the remaining 2. Before the fix, `swatches` was a plain `100%`
    // of `root`, and `root` itself has no explicit width — it auto-fits to its widest child,
    // which is `swatches` itself. That circular relationship meant the rendered footprint tracked
    // how many items the current window actually held, so `root` (and `label` above it, itself
    // 100% of that same `root`) visibly resized between pages — confirmed directly in a running
    // Storybook, where the pagination chevrons jumped position between the two pages of the
    // `Paginated` story.
    const sixColours: ZimmColourSwatchValue[] = [
      BAY_BLUE,
      IVORY,
      BLACK,
      { value: 'EMER', name: 'Emerald', href: '/p.html?color=EMER', imageUrl: IMAGE('emerald') },
      { value: 'CORAL', name: 'Coral', href: '/p.html?color=CORAL', imageUrl: IMAGE('coral') },
      { value: 'NAVY', name: 'Navy', href: '/p.html?color=NAVY', imageUrl: IMAGE('navy') },
    ];

    renderGroup({ selectedName: BAY_BLUE.name, selectedValue: BAY_BLUE.value, values: sixColours });
    expect(screen.getAllByRole('radio')).toHaveLength(4);

    // jsdom has no real layout engine — getBoundingClientRect() reads 0 for every element
    // regardless of whether the fix is applied, which would make a before/after comparison pass
    // even against the pre-fix code (a false negative that proves nothing). getComputedStyle
    // *does* reliably read back the literal declared CSS value for a Chakra/emotion-authored
    // style in this codebase's jsdom setup — the same technique the "resolves its recipe under a
    // ChakraProvider" test above already relies on for `gap`.
    const widthBefore = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;

    // Pinned to the specific reserved-footprint expression — and explicitly not the old `100%` —
    // rather than just compared against the post-click reading. A plain `100%` is ALSO textually
    // identical to itself before and after clicking "next" (the literal declared string never
    // changes; only what it resolves against would, which jsdom cannot compute). Without this,
    // a same-value-both-times check alone would pass against the pre-fix code too and would not
    // actually catch the regression.
    const PAGE_SIZE = 4;
    const expectedWidth = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;
    expect(widthBefore).toBe(expectedWidth);
    expect(widthBefore).not.toBe('100%');

    await userEvent.click(screen.getByRole('button', { name: /next colours/i }));

    // Now on the final, partial (2-item) page.
    expect(screen.getAllByRole('radio')).toHaveLength(2);

    const widthAfter = window.getComputedStyle(screen.getByRole('radiogroup', { name: 'Colour' })).width;
    expect(widthAfter).toBe(widthBefore);
    expect(widthAfter).not.toBe('100%');
  });

  test('truncates a long selected colour name, and only the dynamic name — never the static "Colour:" label', () => {
    // 70 characters — well past anything the labelName column could render on one line, so this
    // is a real exercise of the Figma interaction annotation ("If Label/Colour name is longer,
    // use truncation"), not just a token-presence check.
    const LONG_NAME = 'Antique Rose Gold Shimmer Sequin Embellished Iridescent Sunset Ombre';
    expect(LONG_NAME.length).toBeGreaterThan(60);

    renderGroup({ selectedName: LONG_NAME, selectedValue: 'BAYBL' });

    const dynamicNameStyles = window.getComputedStyle(screen.getByText(LONG_NAME));
    expect(dynamicNameStyles.overflow).toBe('hidden');
    expect(dynamicNameStyles.textOverflow).toBe('ellipsis');
    expect(dynamicNameStyles.whiteSpace).toBe('nowrap');

    // The static "Colour:" text beside it is never meant to truncate — only the dynamic name
    // carries the Figma-mandated behaviour above.
    const staticLabelStyles = window.getComputedStyle(screen.getByText('Colour:'));
    expect(staticLabelStyles.textOverflow).not.toBe('ellipsis');
  });
});
